import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-santidad-ii', 'C',
 [dict(t=2523, e=2578, titulo='Un camino que lleva luz', txt='El camino de santidad: lo bonito es que, por muy torpe que sea, usted no va a tropezar, porque ese camino lleva luz. La santidad es una clase de luz. Y entonces usted dice: «Ay, ahí hay un hoyo», pero no se va en él, porque Dios le alumbra el camino, y por eso usted no tropieza. Tiene que estar listo. […] Y entonces usted por ese camino va a ir creciendo. A mí se me hace que ese camino no va recto: va para arriba. […] Pero dice: «Habrá allí un camino y calzada, y se llamará Camino de Santidad».'),
  dict(t=3156, e=3246, titulo='La mente de Cristo', txt='Usted va a empezar a hablar bien, no a hablar mal. Le van a venir pensamientos feos, y rápido los va a reprender. Ya no va a dejar que entren, se estacionen en su mente, y entonces, hermano, se vuelve un circo. […] Pero Dios lo que quiere es que usted tenga la mente de Cristo, porque con la mente de Cristo usted sabe cómo piensa el Padre a través del Hijo, sabe lo que hace el Padre a través del Hijo. Y entonces, con la mente de Cristo, va a agradar a Dios. Cristo no tiene malos pensamientos. Cristo no tiene pensamientos de pecado. Cristo no tiene pensamientos de venganza. […] Cristo quiere hacerle el bien todos los días al que se deje. Por eso dice: «Cada mañana son nuevas mis bendiciones». Tú no has abierto tus ojos y él ya está ahí viendo cómo te bendice. Igual el Padre; entonces tú tienes que ser recíproco.'),
  dict(t=4757, e=4806, titulo='Una iglesia justa y resplandeciente', txt='Dios quiere que toda pobreza se vaya de tu vida. En el nombre de Jesús, te veo próspero, te veo bendecido, y le creo a Dios que el Espíritu de santidad cae hoy sobre tu vida, y que eso va a cambiar y te va a redarguir de todo pecado, de toda iniquidad, de toda transgresión, y le vas a servir al Señor con todo tu corazón. Pídele al Señor que te limpie tu mente, que quite todo pecado, todo mal pensamiento. Pelea con eso, lucha con eso, y vas a ver que vamos a tener una iglesia hermosa, justa, resplandeciente.')],
 [dict(t=2347, txt='Hay un camino, y ese camino es Cristo.'),
  dict(t=2813, txt='Te tiene en su mano, y de ahí nadie te puede quitar.'),
  dict(t=4137, txt='Si le vamos a servir a Dios, él nos va a dar la capacidad para que seamos santos.')],
 ['Si la santidad es una luz que alumbra el camino, ¿en qué parte de tu vida necesitas hoy que Dios te alumbre para no tropezar?',
  '¿Qué pensamiento feo has dejado «estacionarse» en tu mente, y cómo puedes reprenderlo rápido esta semana y pensar con la mente de Cristo?',
  'Cada mañana son nuevas sus bendiciones: ¿cómo puedes responderle a Dios con gratitud antes de abrir los ojos al día?'])
